const results = [];

for (const item of $input.all()) {
  const output = item.json?.output;

  if (!output || String(output).trim() === "") {
    continue;
  }

  let raw = String(output).trim();

  // Remove markdown fences if present
  raw = raw.replace(/```json|```/gi, "").trim();

  let reply = "";

  // Try parsing JSON
  try {
    const parsed = JSON.parse(raw);
    reply = typeof parsed.reply === "string" ? parsed.reply : "";
  } catch {
    reply = raw;
  }

  if (!reply.trim()) {
    continue;
  }

  // Normalize formatting
  reply = reply
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+\n/g, "\n")
    .trim();

  // Escape newlines ONCE for APIs
  reply = reply.replace(/\n/g, "\\n");

  results.push({
    json: {
      reply
    }
  });
}

// Guarantee output so workflow never breaks
if (results.length === 0) {
  return [
    {
      json: {
        reply: ""
      }
    }
  ];
}

return results;

