const staticData = $getWorkflowStaticData('global');

const msg =
  $json.body?.entry?.[0]?.messaging?.[0]?.message;

const mid = msg?.mid;

if (!mid) {
  return [];
}

if (!staticData.processed) {
  staticData.processed = {};
}

if (staticData.processed[mid]) {
  return [];
}

staticData.processed[mid] = Date.now();

for (const k in staticData.processed) {
  if (Date.now() - staticData.processed[k] > 120000) {
    delete staticData.processed[k];
  }
}

return [$json];

